input.command:
git rm -q context-management/{anthropic-context-editing-docs,anthropic-effective-context-engineering,openhands-context-condenser}.md escalation/{anthropic-advisor-tool,automix,leap-privileged-feedback}.md small-model-agents/{less-is-more-tool-reduction,small-model-database-agent}.md stuck-in-a-loop/{empirical-study-issue-solving-failures,openrouter-doom-loop-detection}.md task-decomposition/{github-spec-kit,kiro-specs,langgraph-graph-and-persistence,plan-and-act,tdd-for-code-generation}.md trajectory-data/{devstral,rome-error-masked-training,swe-dev}.md && python3 - <<'EOF'
import os,re,glob
for d in sorted(glob.glob('*/')):
    p=d+'README.md'; L=open(p).read().split('\n')
    out=[];seen=False
    for l in L:
        if l.startswith('|'):
            seen=True
            m=re.search(r'\]\(([^)]+\.md)\)',l)
            if m and not os.path.exists(d+m.group(1)): continue
            out.append(l)
        elif seen and l.startswith('#'): break
        else: out.append(l)
    open(p,'w').write('\n'.join(out).rstrip()+'\n')
    print(p, sum(1 for l in out if l.startswith('| [')), len(glob.glob(d+'*.md'))-1)
# broken links
for f in glob.glob('*/*.md')+glob.glob('../**/*.md',recursive=True):
    for m in re.finditer(r'\]\(([^)#]+\.md)',open(f).read()):
        t=os.path.normpath(os.path.join(os.path.dirname(f),m.group(1)))
