    print("last call args:", (w.messages[-2].get("tool_calls") or [{}])[0].get("function", {}).get("arguments", "")[:300]);
    raw = post("/apply-template", {"messages": w.messages[:2]});
    print("rendered prompt tail:", repr(raw["prompt"][-120:]));
}
EOF
